def minimalBases(classes):
    """Reduce a list of base classes to its ordered minimum equivalent"""
    seen = set()
    result = []
    for cls in classes:
        if cls in seen:
            continue
        seen.add(cls)
        result.append(cls)
        for base in minimalBases(cls.__bases__):
            if base not in seen:
                seen.add(base)
                result.append(base)
    return result

