def validate_fixity(self, fixity, manifest_files):
    """Validate fixity block in inventory.

    Check the structure of the fixity block and makes sure that only files
    listed in the manifest are referenced.
    """
    if not isinstance(fixity, dict):
        raise ValueError("Fixity must be a dictionary")

    if 'files' not in fixity:
        raise ValueError("Fixity dictionary must contain 'files' key")

    if not isinstance(fixity['files'], list):
        raise ValueError("Fixity 'files' key must be a list")

    for file_info in fixity['files']:
        if 'path' not in file_info:
            raise ValueError("File info must contain 'path' key")
        if 'hash' not in file_info:
            raise ValueError("File info must contain 'hash' key")

    for file_info in fixity['files']:
        if file_info['path'] not in manifest_files:
            raise ValueError(f"File path '{file_info['path']}' not found in manifest")

    try:
        for file_info in fixity['files']:
            codecs.lookup(file_info['hash'])
    except LookupError:
        raise ValueError("Unknown hash algorithm: \"%s\"" % file_info['hash'])

