def bash_completion():
    '''
    Return a bash completion script for the borgmatic command. Produce this by introspecting
    borgmatic's command-line argument parsers.
    '''
    main = click.get_current_context().command
    all_params = sorted(
        main.get_params(click.get_current_context()), key=lambda p: p.param_type_name
    )

    def get_name(param):
        return max(param.opts, key=len)

    for param in all_params:
        if param.param_type_name == "option":
            option = get_name(param)
            same_dest = [
                get_name(p) for p in all_params if p.name == param.name
            ]
            if same_dest:
                option = "({})".format(" ".join(same_dest)) + option
            if param.help:
                option += "[{}]".format(param.help or "")
            if not param.is_flag:
                option += "=:( )"
            click.echo(option)
        elif param.param_type_name == "argument":
            option = get_name(param)
            click.echo(":{}".format(option))

import re

def size_to_bytes(size: str) -> int:
    """Convert human readable file size to bytes.

    Resulting value is an approximation as input value is in most case rounded.

    Args:
        size: A string representing a human readable file size (eg: '500K')

    Returns:
        A decimal representation of file size

        Examples::

            >>> size_to_bytes("500")
            500
            >>> size_to_bytes("1K")
            1000
    """
    size = size.strip()
    if not size:
        return 0

    match = re.match(r'(\d+)([KMGTPEZY]?)', size.upper())
    if not match:
        raise ValueError(f"Invalid size format: {size}")

    number, unit = match.groups()
    number = int(number)

    if unit == 'K':
        return number * 1024
    elif unit == 'M':
        return number * 1024 * 1024
    elif unit == 'G':
        return number * 1024 * 1024 * 1024
    elif unit == 'T':
        return number * 1024 * 1024 * 1024 * 1024
    elif unit == 'P':
        return number * 1024 * 1024 * 1024 * 1024 * 1024
    elif unit == 'E':
        return number * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif unit == 'Z':
        return number * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    elif unit == 'Y':
        return number * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024 * 1024
    else:
        return number

