def make_find_paths(find_paths):
    '''
    Given a sequence of path fragments or patterns as passed to `--find`, transform all path
    fragments into glob patterns. Pass through existing patterns untouched.

    For example, given find_paths of:

      ['foo.txt', 'pp:root/somedir']

    ... transform that into:

      ['sh:**/*foo.txt*/**', 'pp:root/somedir']
    '''
    def is_glob_pattern(path):
        return re.match(r'^\*\*|\*\*[\d]{1,2}|\*\*[\d]{1,2}[\d]{1,2}$', path)

    def transform_glob_pattern(pattern):
        if pattern.endswith('**'):
            if pattern.endswith('**10'):
                return f'sh:**/*{pattern[:-4]}*/**'
            elif pattern.endswith('**9'):
                return f'sh:**/*{pattern[:-3]}*/**'
            elif pattern.endswith('**8'):
                return f'sh:**/*{pattern[:-2]}*/**'
            elif pattern.endswith('**7'):
                return f'sh:**/*{pattern[:-1]}*/**'
            elif pattern.endswith('**6'):
                return f'sh:**/*{pattern[:-1]}*/**'
            elif pattern.endswith('**5'):
                return f'sh:**/*{pattern[:-1]}*/**'
            elif pattern.endswith('**4'):
                return f'sh:**/*{pattern[:-1]}*/**'
            elif pattern.endswith('**3'):
                return f'sh:**/*{pattern[:-1]}*/**'
            elif pattern.endswith('**2'):
                return f'sh:**/*{pattern[:-1]}*/**'
            elif pattern.endswith('**1'):
                return f'sh:**/*{pattern[:-1]}*/**'
            else:
                return f'sh:**/*{pattern[:-2]}*/**'
        else:
            return pattern

    return [transform_glob_pattern(path) if is_glob_pattern(path) else path for path in find_paths]

