def load_configurations(config_filenames, overrides=None, resolve_env=True):
    '''
    Given a sequence of configuration filenames, load and validate each configuration file. Return
    the results as a tuple of: dict of configuration filename to corresponding parsed configuration,
    and sequence of logging.LogRecord instances containing any parse errors.
    '''
    config_dict = {}
    log_records = []

    for filename in config_filenames:
        try:
            if filename.endswith('.toml'):
                with open(filename, 'r') as fd:
                    raw_config = fd.read()
                log_config = toml.loads(raw_config)
            elif filename.endswith('.yaml'):
                with open(filename, 'r') as fd:
                    raw_config = fd.read()
                log_config = yaml.safe_load(raw_config)
            else:
                log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, f'Unsupported file format: {filename}'))
                continue

            if overrides:
                log_config.update(overrides)

            if resolve_env:
                log_config = _resolve_env_vars(log_config)

            config_dict[filename] = log_config

        except Exception as e:
            log_records.append(logging.LogRecord('load_configurations', logging.ERROR, filename, 0, f'Error loading {filename}: {e}'))

    return config_dict, log_records

def _resolve_env_vars(config):
    """
    Resolve environment variables in the configuration dictionary.
    """
    import re
    import os

    def replace_env_var(match):
        var_name = match.group(1)
        return os.getenv(var_name, match.group(0))

    for key, value in config.items():
        if isinstance(value, str):
            config[key] = re.sub(r'\${([^}]+)}', replace_env_var, value)

    return config

